// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";
import * as React from "react";
import { Progress as ProgressPrimitive } from "./primitive-progress";
import { cn } from "./utils";
function Progress({
  className,
  value,
  max = 100,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root>) {
  const maximum = Number.isFinite(max) && max > 0 ? max : 100;
  const current =
    typeof value === "number" && Number.isFinite(value)
      ? Math.max(0, Math.min(maximum, value))
      : null;
  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      className={cn("roc-ui", className)}
      {...props}
      value={current}
      max={maximum}
    >
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="roc-ui"
        style={
          current === null
            ? undefined
            : { transform: `scaleX(${current / maximum})` }
        }
      />
    </ProgressPrimitive.Root>
  );
}
export { Progress };

import "./progress.css";

"use client";
// ROC primitive: a determinate or indeterminate progress bar.
import * as React from "react";

type State = "indeterminate" | "complete" | "loading";
const Context = React.createContext<{ value: number | null; max: number }>({
  value: null,
  max: 100,
});

const stateOf = (value: number | null, max: number): State =>
  value == null ? "indeterminate" : value === max ? "complete" : "loading";

type RootProps = Omit<React.ComponentProps<"div">, "children"> & {
  children?: React.ReactNode;
  value?: number | null;
  max?: number;
  getValueLabel?: (value: number, max: number) => string;
};

function Root({
  value: requested,
  max: requestedMax,
  getValueLabel = (value, max) => `${Math.round((value / max) * 100)}%`,
  ...props
}: RootProps) {
  const max = requestedMax && requestedMax > 0 ? requestedMax : 100;
  const value =
    typeof requested === "number" && requested >= 0 && requested <= max
      ? requested
      : null;
  return (
    <Context.Provider value={{ value, max }}>
      <div
        role="progressbar"
        aria-valuemax={max}
        aria-valuemin={0}
        aria-valuenow={value ?? undefined}
        aria-valuetext={value === null ? undefined : getValueLabel(value, max)}
        data-state={stateOf(value, max)}
        data-value={value ?? undefined}
        data-max={max}
        {...props}
      />
    </Context.Provider>
  );
}

function Indicator(props: React.ComponentProps<"div">) {
  const { value, max } = React.useContext(Context);
  return (
    <div
      data-state={stateOf(value, max)}
      data-value={value ?? undefined}
      data-max={max}
      {...props}
    />
  );
}

export const Progress = { Root, Indicator };

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="progress"] {
  height: 6px;
  width: 100%;
  overflow: hidden;
  border-radius: 99px;
  background: var(--roc-line, #e5e5e5);
}
.roc-ui[data-slot="progress-indicator"] {
  width: 100%;
  height: 100%;
  background: var(--roc-accent, var(--roc-ink, #252525));
  transform-origin: left;
  transition: transform var(--roc-motion-medium) var(--roc-motion-ease);
}
.roc-ui[data-slot="progress"][dir="rtl"] [data-slot="progress-indicator"] {
  transform-origin: right;
}
.roc-ui[data-slot="progress-indicator"][data-state="indeterminate"] {
  width: 35%;
  animation: roc-progress-pending 1.4s ease-in-out infinite;
}
@keyframes roc-progress-pending {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(290%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui[data-slot="progress-indicator"][data-state="indeterminate"] {
    animation: none;
    width: 50%;
    transform: none;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
